package com.cryptostrategy.platform.persistence.reproduction;
import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.backtesting.internal.BacktestReproductionVerifier;import com.cryptostrategy.platform.persistence.api.BacktestingPersistenceFactory;import com.cryptostrategy.platform.persistence.support.F006DatabaseFixture;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;
class ReproductionPersistenceIntegrationTest{@Test void readBackVerificationNeverOverwritesOriginalEvidence(){var source=F006DatabaseFixture.dataSource();F006DatabaseFixture.transaction(source).executeWithoutResult(status->{status.setRollbackOnly();var jdbc=new JdbcTemplate(source);F006DatabaseFixture.seed(jdbc);var factory=new BacktestingPersistenceFactory(source);var original=F006DatabaseFixture.result();factory.createResultStore().save(original);var reloaded=factory.createResultReader().findById(original.resultId()).orElseThrow();assertTrue(new BacktestReproductionVerifier().verify(original,reloaded).matched());assertEquals(1,jdbc.queryForObject("select count(*) from experiment.backtest_result where backtest_result_id=?",Integer.class,original.resultId().value()));});}}
